// Parse ###LEAD_DATA###...###END_LEAD_DATA### from the AI's reply.
// Supports both fenced (```json ... ```) and unfenced JSON between markers.
// Strips the entire block from the user-visible reply.

const raw = $json.output ?? $json.text ?? $json.response ?? '';

// Match everything between the markers (greedy enough to capture any JSON,
// optional whitespace, optional ```json fences on either side).
const markerRegex = /###LEAD_DATA###([\s\S]*?)###END_LEAD_DATA###/m;
const match = raw.match(markerRegex);

let leadCaptured = false;
let lead = null;
let cleanReply = raw;

if (match) {
  // Strip ```json / ``` fences if the model included them
  const inner = match[1]
    .replace(/^\s*```(?:json)?\s*/i, '')
    .replace(/\s*```\s*$/i, '')
    .trim();
  try {
    lead = JSON.parse(inner);
    leadCaptured = Boolean(lead.name && lead.service);
    cleanReply = raw.replace(markerRegex, '').trim();
  } catch (err) {
    console.warn('LEAD_DATA JSON parse failed:', err.message, 'Inner:', inner);
  }
}

const trigger = $('WhatsApp Trigger').first().json;
const phone = trigger.messages?.[0]?.from ?? '';
const waName = trigger.contacts?.[0]?.profile?.name ?? '';

return {
  json: { cleanReply, leadCaptured, lead, phone, waName, rawAgentOutput: raw }
};

// ILOT FAQ knowledge-base tool.
// The agent passes a natural-language `query`; we fetch active FAQs from
// NocoDB live and return the best-matching Q&A pairs as plain text.
//
// Lexical scoring (no embeddings) is plenty for ~60 short rows and always
// reflects the current NocoDB content. Edit a FAQ in NocoDB -> next message
// sees it.

const NOCODB_BASE = 'https://nocodb.ilotlegal.com';
const TABLE = 'miltd46do8tcznj';
const TOKEN=*** // set in n8n env/vars; falls back below

const token = TOKEN || '__REDACTED_SEE_PRODUCTION_N8N__';

const url = `${NOCODB_BASE}/api/v2/tables/${TABLE}/records?where=${encodeURIComponent('(Active,eq,1)')}&limit=200&fields=${encodeURIComponent('Question,Answer,Department')}`;

let rows = [];
try {
  const resp = await this.helpers.httpRequest({
    method: 'GET',
    url,
    headers: { 'xc-token': token },
    json: true,
  });
  rows = resp.list || [];
} catch (e) {
  return 'FAQ lookup temporarily unavailable.';
}

const q = String(query || '').toLowerCase();
const stop = new Set(['the','a','an','is','are','do','does','i','to','of','for','and','what','how','can','my','in','on','you','your','with','at','it','this']);
const terms = q.split(/[^a-z0-9]+/).filter(t => t.length > 2 && !stop.has(t));

function score(row) {
  const hay = `${row.Question} ${row.Answer} ${row.Department}`.toLowerCase();
  let s = 0;
  for (const t of terms) {
    if (hay.includes(t)) s += 1;
    if (String(row.Question).toLowerCase().includes(t)) s += 1; // question match weighted
  }
  return s;
}

const ranked = rows
  .map(r => ({ r, s: score(r) }))
  .filter(x => x.s > 0)
  .sort((a, b) => b.s - a.s)
  .slice(0, 3);

if (ranked.length === 0) {
  return 'No FAQ entry closely matches that. Answer from general knowledge of ILOT services, or offer to connect a human specialist.';
}

return ranked
  .map(({ r }) => `[${r.Department}]\nQ: ${r.Question}\nA: ${r.Answer}`)
  .join('\n\n---\n\n');

// Commitment-gate token generator.
// Runs on the 'lead captured = true' branch. Generates a CASE-XXXX token,
// builds the WhatsApp commitment-ask message, and carries forward the lead
// fields so the NocoDB Create node and the Send node can both read them.

function makeToken() {
  const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; // no confusing 0/O/1/I
  let s = '';
  for (let i = 0; i < 4; i++) s += chars[Math.floor(Math.random() * chars.length)];
  return s;
}

const p = $json; // from Parse Lead Datat (reach-back preserved by connection)
const token = makeToken();
const caseId = 'CASE-' + token;

// Per-service required docs. Extend this map as the Indonesia team confirms
// the real doc list per service category (commitment-gate-flow.md open Q#3).
const DOCS_BY_DEPARTMENT = {
  'VISA': ['Copy of passport (PDF or photo)', 'Proof of address (utility bill / bank statement)'],
  'COMPANY SETUP': ['Copy of passport', 'Proposed company name(s)', 'Proof of address'],
  'LEGAL': ['Copy of passport', 'The document(s) you want reviewed (PDF)'],
  'TAX': ['Copy of passport', 'NPWP if you have one']
};
const dept = (p.lead && p.lead.department ? String(p.lead.department) : '').toUpperCase();
let docs = DOCS_BY_DEPARTMENT[dept];
if (!docs) docs = ['Copy of passport (PDF or photo)', 'Proof of address (utility bill / bank statement)'];

const docLines = docs.map(d => '   \u2022 ' + d).join('\n');

const askMessage =
  'Great \u2014 we\u2019re ready to assign your case officer. \ud83c\udf89\n\n' +
  'Please email the following to legal.admin@ilotpropertybali.com:\n' +
  docLines + '\n\n' +
  'Use this exact subject line so we route it correctly:\n' +
  '   [' + caseId + ']\n\n' +
  'The moment we receive it, your assigned officer will reply here on WhatsApp.';

return {
  json: {
    ...p,
    commitment_token: token,
    case_id: caseId,
    required_docs: docs,
    commitment_status: 'awaiting_email',
    askMessage
  }
};
